/* DM Sans is bundled (SIL Open Font License, see fonts/OFL.txt) so the app works offline. */
@font-face { font-family: "DM Sans"; src: url("fonts/DMSans-300.ttf") format("truetype"); font-weight: 300; font-style: normal; font-display: swap; }
@font-face { font-family: "DM Sans"; src: url("fonts/DMSans-400.ttf") format("truetype"); font-weight: 400; font-style: normal; font-display: swap; }
@font-face { font-family: "DM Sans"; src: url("fonts/DMSans-500.ttf") format("truetype"); font-weight: 500; font-style: normal; font-display: swap; }
@font-face { font-family: "DM Sans"; src: url("fonts/DMSans-600.ttf") format("truetype"); font-weight: 600; font-style: normal; font-display: swap; }

:root {
  --ink: #0b0b0b;
  --ink-2: #52514e;
  --muted: #898781;
  --line: rgba(11, 11, 11, 0.08);
  --page: #f6f5f1;
  --surface: #ffffff;
  --wet: #2a78d6;
  --wet-lt: #b7d3f6;
  --dry: #eb6834;
  --dry-lt: #f0efec;
  --missing: #a9a79f;
  --max: 1560px;
  --gutter: 24px;
}

/* The app uses the stock precompiled Bootstrap 5 theme (no Sass at start-up), so the
   brand settings are applied here through Bootstrap's own CSS variables. */
:root, [data-bs-theme="light"] {
  --bs-body-font-family: "DM Sans", system-ui, sans-serif;
  --bs-body-font-size: 0.95rem;
  --bs-body-color: var(--ink);
  --bs-body-color-rgb: 11, 11, 11;
  --bs-body-bg: var(--page);
  --bs-emphasis-color: var(--ink);
  --bs-secondary-color: var(--ink-2);
  --bs-primary: var(--wet);
  --bs-primary-rgb: 42, 120, 214;
  --bs-link-color: var(--wet);
  --bs-link-color-rgb: 42, 120, 214;
  --bs-link-hover-color: #1c5cab;
  --bs-link-hover-color-rgb: 28, 92, 171;
  --bs-border-color: rgba(11, 11, 11, 0.12);
  --bs-border-radius: 0.6rem;
  --bs-border-radius-sm: 0.45rem;
  --bs-border-radius-lg: 1rem;
  --bs-focus-ring-color: rgba(42, 120, 214, 0.3);
  --bs-heading-color: var(--ink);
}
h1, h2, h3, h4, h5, h6 { font-weight: 500; font-family: "DM Sans", system-ui, sans-serif; }
.btn-primary {
  --bs-btn-color: #fff;
  --bs-btn-bg: var(--wet);
  --bs-btn-border-color: var(--wet);
  --bs-btn-hover-color: #fff;
  --bs-btn-hover-bg: #256abf;
  --bs-btn-hover-border-color: #256abf;
  --bs-btn-active-color: #fff;
  --bs-btn-active-bg: #1c5cab;
  --bs-btn-active-border-color: #1c5cab;
  --bs-btn-focus-shadow-rgb: 42, 120, 214;
}
.btn-outline-primary {
  --bs-btn-color: var(--wet);
  --bs-btn-border-color: var(--wet);
  --bs-btn-hover-color: #fff;
  --bs-btn-hover-bg: var(--wet);
  --bs-btn-hover-border-color: var(--wet);
  --bs-btn-active-color: #fff;
  --bs-btn-active-bg: #1c5cab;
  --bs-btn-active-border-color: #1c5cab;
  --bs-btn-focus-shadow-rgb: 42, 120, 214;
}
.bslib-sidebar-resize-handle { display: none !important; }

html, body { background: var(--page); }
body {
  color: var(--ink);
  font-family: "DM Sans", system-ui, sans-serif;
  font-size: 0.95rem;
  font-weight: 400;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

/* Navigation ------------------------------------------------------------------ */
.navbar {
  background: var(--surface) !important;
  border-bottom: 1px solid var(--line);
  padding-block: 0.4rem;
}
.navbar > .container-fluid { max-width: var(--max); margin: 0 auto; padding-inline: var(--gutter); }
.navbar-brand { margin-right: 1.75rem; }
.brand { display: inline-flex; align-items: center; gap: 0.6rem; font-weight: 500; letter-spacing: -0.015em; font-size: 1.02rem; color: var(--ink); }
.brand-dot { width: 10px; height: 10px; border-radius: 50% 50% 50% 0; transform: rotate(-45deg); background: var(--wet); }
.navbar .nav-link { color: var(--ink-2) !important; font-weight: 400; padding-inline: 0.75rem !important; border-radius: 8px; }
.navbar .nav-link:hover { color: var(--ink) !important; background: rgba(11, 11, 11, 0.04); }
.navbar .nav-link.active { color: var(--ink) !important; font-weight: 500; background: rgba(42, 120, 214, 0.09); }
.nav-meta { color: var(--muted); font-size: 0.8rem; white-space: nowrap; }

/* Page frame ------------------------------------------------------------------ */
.tab-content { max-width: var(--max); margin: 0 auto; padding: 1.5rem var(--gutter) 2.5rem; }
.tab-content > .tab-pane > .page,
.tab-content > .tab-pane > .bslib-sidebar-layout { display: flex; flex-direction: column; gap: 1rem; }
.bslib-sidebar-layout { border: 0 !important; border-radius: 0 !important; background: transparent !important; --_sidebar-bg: transparent; }
.bslib-sidebar-layout > .main { padding: 0 0 0 1.75rem !important; display: flex; flex-direction: column; gap: 1rem; overflow: visible; }
.bslib-sidebar-layout > .sidebar { border-right: 1px solid var(--line) !important; background: transparent !important; }
.bslib-sidebar-layout > .sidebar > .sidebar-content { padding: 0.25rem 1.25rem 1rem 0 !important; position: sticky; top: 1rem; }
.bslib-sidebar-layout .collapse-toggle { display: none; }

.page-head { margin: 0.25rem 0 0.5rem; }
.page-head h1 {
  font-size: clamp(1.7rem, 1.15rem + 1.5vw, 2.4rem);
  font-weight: 500;
  letter-spacing: -0.03em;
  line-height: 1.08;
  margin: 0 0 0.6rem;
  max-width: 22ch;
}
.lede, .lede p { color: var(--ink-2); font-size: 1.02rem; line-height: 1.55; max-width: 72ch; margin: 0; }

/* Cards ----------------------------------------------------------------------- */
.bslib-grid { gap: 1rem !important; margin: 0 !important; }
.card {
  border: 1px solid var(--line);
  border-radius: 16px;
  box-shadow: none;
  background: var(--surface);
  margin: 0 !important;
}
.card-header {
  background: transparent;
  border: 0;
  padding: 1.05rem 1.3rem 0.15rem;
  font-weight: 500;
  font-size: 1rem;
  letter-spacing: -0.012em;
}
.card-header.with-action { display: flex; align-items: center; justify-content: space-between; gap: 0.6rem 1rem; flex-wrap: wrap; }
.card-body { padding: 0.7rem 1.3rem 1.15rem; gap: 0.5rem; }
.caption { color: var(--muted); font-size: 0.8rem; line-height: 1.45; margin: 0.35rem 0 0; }
.note { color: var(--ink-2); font-size: 0.84rem; line-height: 1.5; margin: 0.75rem 0 0; }
.girafe_container_std, .girafe_container_std svg { width: 100% !important; }
.html-widget.girafe { margin: 0; }

/* Sidebar choices ---------------------------------------------------------------- */
.picker .shiny-input-container { width: 100%; margin-bottom: 1.25rem; }
.picker .control-label, .slider-label {
  font-size: 0.72rem;
  text-transform: uppercase;
  letter-spacing: 0.07em;
  color: var(--muted);
  font-weight: 500;
  margin-bottom: 0.4rem;
}
.picker .shiny-options-group { display: flex; flex-direction: column; gap: 2px; }
.picker .radio, .picker .form-check { margin: 0; padding: 0; min-height: 0; }
.picker .radio label, .picker .form-check-label {
  display: flex; align-items: center; width: 100%;
  padding: 0.45rem 0.7rem; border-radius: 10px;
  cursor: pointer; color: var(--ink-2); font-size: 0.92rem;
  transition: background 0.15s ease, color 0.15s ease;
}
.picker input[type="radio"] { position: absolute; opacity: 0; pointer-events: none; }
.picker .radio label:hover { background: rgba(11, 11, 11, 0.04); color: var(--ink); }
.picker .radio label:has(input:checked) { background: rgba(42, 120, 214, 0.1); color: var(--ink); font-weight: 500; }
.picker .radio label:has(input:focus-visible) { outline: 2px solid var(--wet); outline-offset: 1px; }
.side-note { color: var(--muted); font-size: 0.8rem; line-height: 1.5; margin: 0.25rem 0 0; }

/* Segmented choice in a card header */
.card-header .shiny-input-container { margin: 0; width: auto; }
.card-header .shiny-options-group { display: inline-flex; background: #f1f0ec; border-radius: 10px; padding: 3px; gap: 2px; }
.card-header .radio-inline, .card-header .form-check-inline {
  margin: 0 !important; padding: 0.3rem 0.85rem !important; border-radius: 8px;
  font-size: 0.85rem; color: var(--ink-2); cursor: pointer; font-weight: 400;
}
.card-header input[type="radio"] { position: absolute; opacity: 0; pointer-events: none; }
.card-header .radio-inline:has(input:checked) { background: #fff; color: var(--ink); font-weight: 500; box-shadow: 0 1px 2px rgba(11, 11, 11, 0.1); }
.card-header .radio-inline:has(input:focus-visible) { outline: 2px solid var(--wet); }

.btn { font-weight: 500; border-radius: 10px; }
.btn-sm { padding: 0.32rem 0.85rem; font-size: 0.84rem; }

/* Transition matrix --------------------------------------------------------------- */
.matrix { display: grid; grid-template-columns: auto minmax(0, 1fr) minmax(0, 1fr); gap: 6px; }
.m-head { font-size: 0.78rem; color: var(--muted); text-align: center; align-self: end; }
.m-row { font-size: 0.84rem; color: var(--ink-2); display: flex; align-items: center; padding-right: 0.6rem; }
.tile { border-radius: 12px; padding: 1.05rem 0.75rem; text-align: center; }
.tile.wet { background: rgba(42, 120, 214, calc(0.07 + var(--a) * 0.5)); }
.tile.dry { background: rgba(235, 104, 52, calc(0.06 + var(--a) * 0.36)); }
.tile-p { font-size: 2rem; font-weight: 300; letter-spacing: -0.035em; line-height: 1.05; font-variant-numeric: tabular-nums; }
.tile-ci { font-size: 0.76rem; color: var(--ink-2); margin-top: 0.25rem; font-variant-numeric: tabular-nums; }

/* Facts and tests ------------------------------------------------------------------ */
.facts { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 0.75rem; padding-bottom: 1rem; margin-bottom: 0.9rem; border-bottom: 1px solid var(--line); }
.fact-v { font-size: 1.6rem; font-weight: 300; letter-spacing: -0.03em; line-height: 1.1; font-variant-numeric: tabular-nums; }
.fact-l { font-size: 0.8rem; color: var(--muted); margin-top: 0.2rem; }
.test + .test { margin-top: 0.85rem; }
.test-q { font-weight: 500; font-size: 0.93rem; display: flex; gap: 0.5rem; align-items: baseline; }
.test-tag { font-size: 0.68rem; font-weight: 500; color: var(--wet); background: rgba(42, 120, 214, 0.1); border-radius: 6px; padding: 0.1rem 0.4rem; letter-spacing: 0.03em; }
.test-a { margin: 0.25rem 0 0.15rem; font-size: 0.9rem; line-height: 1.5; }
.test-s { margin: 0; color: var(--muted); font-size: 0.8rem; }

/* Legends and verdicts ------------------------------------------------------------- */
.legend { display: flex; flex-wrap: wrap; align-items: center; gap: 0.35rem 1.1rem; font-size: 0.8rem; color: var(--ink-2); }
.legend .li { display: inline-flex; align-items: center; gap: 0.4rem; }
.key { display: inline-block; flex: none; }
.key-dot { width: 9px; height: 9px; border-radius: 50%; }
.key-dot.wet { background: var(--wet); }
.key-dot.dry { background: var(--dry); }
.key-dot.grey { background: #bdbcb5; }
.key-line { width: 20px; height: 10px; border-radius: 2px; background: linear-gradient(var(--ink-2), var(--ink-2)) center / 100% 2px no-repeat, rgba(11, 11, 11, 0.08); }
.key-sq { width: 11px; height: 11px; border-radius: 3px; }
.key-sq.wet { background: var(--wet); }
.key-sq.light { background: var(--wet-lt); }
.key-sq.dry { background: var(--dry-lt); box-shadow: inset 0 0 0 1px rgba(11, 11, 11, 0.06); }
.key-sq.missing { background: var(--missing); }
.verdict { display: flex; gap: 0.6rem; align-items: baseline; font-size: 0.88rem; line-height: 1.5; margin-top: 0.35rem; }
.verdict .key-dot { position: relative; top: -1px; }

/* Tables ------------------------------------------------------------------------- */
.tbl { width: 100%; border-collapse: collapse; font-size: 0.86rem; font-variant-numeric: tabular-nums; }
.tbl th { font-weight: 500; color: var(--muted); font-size: 0.72rem; text-transform: uppercase; letter-spacing: 0.06em; text-align: left; padding: 0.4rem 0.5rem; border-bottom: 1px solid var(--line); }
.tbl td { padding: 0.55rem 0.5rem; border-bottom: 1px solid var(--line); vertical-align: top; }
.tbl tr:last-child td { border-bottom: 0; }
.tbl tr.best { background: rgba(42, 120, 214, 0.06); }
.tbl tr.best td:first-child { font-weight: 500; }
.tbl .sub { color: var(--muted); font-size: 0.76rem; margin-top: 0.1rem; font-weight: 400; }
.tbl tr.extrap td { color: var(--muted); }
.tbl.compact td, .tbl.compact th { padding: 0.4rem 0.5rem; }
.tbl tr.on td { color: var(--ink); font-weight: 500; }
.tbl tr.on td:first-child { box-shadow: inset 3px 0 0 var(--wet); }
.rule { font-size: 1.05rem; line-height: 1.45; letter-spacing: -0.01em; margin: 0.4rem 0 0.75rem; }

/* Data page ----------------------------------------------------------------------- */
.specs { display: grid; grid-template-columns: repeat(5, minmax(0, 1fr)); gap: 1rem 1.5rem; padding-top: 0.25rem; }
.spec-l { font-size: 0.72rem; text-transform: uppercase; letter-spacing: 0.07em; color: var(--muted); font-weight: 500; margin-bottom: 0.3rem; }
.spec-v { font-size: 0.9rem; line-height: 1.45; }
ol.audit { margin: 0; padding-left: 1.2rem; column-gap: 2.75rem; }
ol.audit li { margin: 0 0 0.65rem; line-height: 1.5; font-size: 0.9rem; break-inside: avoid; }
ol.audit li::marker { color: var(--muted); font-size: 0.8rem; }
@media (min-width: 992px) { ol.audit { columns: 2; } }
@media (max-width: 1199.98px) { .specs { grid-template-columns: repeat(3, minmax(0, 1fr)); } }
@media (max-width: 767.98px) { .specs { grid-template-columns: minmax(0, 1fr); } }

/* Sliders ------------------------------------------------------------------------- */
.irs--shiny .irs-bar { background: var(--wet); border-color: var(--wet); }
.irs--shiny .irs-single { background: var(--ink); color: #fff; font-family: "DM Sans", sans-serif; font-size: 0.78rem; padding: 2px 7px; border-radius: 6px; }
.irs--shiny .irs-handle { border-color: var(--wet); background: var(--wet); }
.irs--shiny .irs-handle:hover, .irs--shiny .irs-handle.state_hover { background: #256abf; }
.irs--shiny .irs-min, .irs--shiny .irs-max { background: transparent; color: var(--muted); }
.irs--shiny .irs-grid-text { color: var(--muted); }
.form-group .control-label { font-weight: 500; font-size: 0.88rem; }

/* Small screens ------------------------------------------------------------------- */
@media (max-width: 991.98px) {
  :root { --gutter: 16px; }
  .nav-meta { display: none; }
  .bslib-sidebar-layout > .main { padding-left: 1.25rem !important; }
}
@media (max-width: 575.98px) {
  .bslib-sidebar-layout > .main { padding: 0 !important; }
  .bslib-sidebar-layout > .sidebar { border-right: 0 !important; border-bottom: 1px solid var(--line) !important; margin-bottom: 1rem; }
  .bslib-sidebar-layout > .sidebar > .sidebar-content { position: static; padding: 0 0 0.75rem !important; }
  .picker .shiny-input-container { margin-bottom: 0.75rem; }
  .picker .shiny-options-group { display: grid; grid-template-columns: minmax(0, 1fr) minmax(0, 1fr); gap: 4px; }
  .picker .radio label { padding: 0.4rem 0.7rem; background: rgba(11, 11, 11, 0.035); }
  .picker .side-note { display: none; }
  .facts { gap: 0.5rem; }
  .fact-v { font-size: 1.2rem; }
  .fact-l { font-size: 0.74rem; }
  .tile { padding: 0.8rem 0.5rem; }
  .tile-p { font-size: 1.6rem; }
  .card-header, .card-body { padding-inline: 1rem; }
  .page-head h1 { max-width: none; }
}
